   152→            RpcLimits::new(altair_fixed_len, altair_fixed_len)
   153→        }
   154→        ForkName::Capella => {
   155→            RpcLimits::new(altair_fixed_len, *LIGHT_CLIENT_UPDATES_BY_RANGE_CAPELLA_MAX)
   156→        }
   157→        ForkName::Deneb => {
   158→            RpcLimits::new(altair_fixed_len, *LIGHT_CLIENT_UPDATES_BY_RANGE_DENEB_MAX)
   159→        }
   160→        ForkName::Electra | ForkName::Fulu | ForkName::Gloas => {
