   697→    /// Handle a `BlocksByRange` request from the peer.
   698→    async fn handle_blocks_by_range_request_inner(
   699→        self: Arc<Self>,
   700→        peer_id: PeerId,
   701→        inbound_request_id: InboundRequestId,
   702→        req: BlocksByRangeRequest,
   703→    ) -> Result<(), (RpcErrorResponse, &'static str)> {
   704→        let req_start_slot = *req.start_slot();
   705→        let req_count = *req.count();
   706→
   707→        debug!(
   708→            %peer_id,
   709→            count = req_count,
   710→            start_slot = %req_start_slot,
   711→            "Received BlocksByRange Request"
   712→        );
   713→
   714→        // Spawn a blocking handle since get_block_roots_for_slot_range takes a sync lock on the
   715→        // fork-choice.
   716→        let network_beacon_processor = self.clone();
   717→        let block_roots = self
   718→            .executor
   719→            .spawn_blocking_handle(
   720→                move || {
   721→                    network_beacon_processor.get_block_roots_for_slot_range(
   722→                        req_start_slot,
   723→                        req_count,
   724→                        "BlocksByRange",
   725→                    )
   726→                },
   727→                "get_block_roots_for_slot_range",
   728→            )
   729→            .ok_or((RpcErrorResponse::ServerError, "shutting down"))?
   730→            .await
   731→            .map_err(|_| (RpcErrorResponse::ServerError, "tokio join"))??;
   732→
   733→        let current_slot = self
   734→            .chain
   735→            .slot()
   736→            .unwrap_or_else(|_| self.chain.slot_clock.genesis_slot());
   737→
   738→        let log_results = |peer_id, blocks_sent| {
   739→            if blocks_sent < (req_count as usize) {
   740→                debug!(
   741→                    %peer_id,
   742→                    msg = "Failed to return all requested blocks",
   743→                    start_slot = %req_start_slot,
   744→                    %current_slot,
   745→                    requested = req_count,
   746→                    returned = blocks_sent,
   747→                    "BlocksByRange outgoing response processed"
   748→                );
   749→            } else {
   750→                debug!(
   751→                    %peer_id,
   752→                    start_slot = %req_start_slot,
   753→                    %current_slot,
   754→                    requested = req_count,
   755→                    returned = blocks_sent,
   756→                    "BlocksByRange outgoing response processed"
   757→                );
   758→            }
   759→        };
   760→
   761→        let mut block_stream = match self.chain.get_blocks(block_roots) {
   762→            Ok(block_stream) => block_stream,
   763→            Err(e) => {
   764→                error!(error = ?e, "Error getting block stream");
   765→                return Err((RpcErrorResponse::ServerError, "Iterator error"));
   766→            }
   767→        };
   768→
   769→        // Fetching blocks is async because it may have to hit the execution layer for payloads.
   770→        let mut blocks_sent = 0;
   771→        while let Some((root, result)) = block_stream.next().await {
   772→            match result.as_ref() {
   773→                Ok(Some(block)) => {
   774→                    // Due to skip slots, blocks could be out of the range, we ensure they
   775→                    // are in the range before sending
   776→                    if block.slot() >= req_start_slot && block.slot() < req_start_slot + req.count()
   777→                    {
   778→                        blocks_sent += 1;
   779→                        self.send_network_message(NetworkMessage::SendResponse {
   780→                            peer_id,
   781→                            inbound_request_id,
   782→                            response: Response::BlocksByRange(Some(block.clone())),
   783→                        });
   784→                    }
   785→                }
   786→                Ok(None) => {
   787→                    error!(
   788→                        request = ?req,
   789→                        %peer_id,
   790→                        request_root = ?root,
   791→                        "Block in the chain is not in the store"
   792→                    );
   793→                    log_results(peer_id, blocks_sent);
   794→                    return Err((RpcErrorResponse::ServerError, "Database inconsistency"));
   795→                }
   796→                Err(BeaconChainError::BlockHashMissingFromExecutionLayer(_)) => {
   797→                    debug!(
   798→                        block_root = ?root,
   799→                        reason = "execution layer not synced",
   800→                        "Failed to fetch execution payload for blocks by range request"
   801→                    );
   802→                    log_results(peer_id, blocks_sent);
   803→                    // send the stream terminator
   804→                    return Err((
   805→                        RpcErrorResponse::ResourceUnavailable,
   806→                        "Execution layer not synced",
   807→                    ));
   808→                }
   809→                Err(e) => {
   810→                    if matches!(
   811→                        e,
   812→                        BeaconChainError::ExecutionLayerErrorPayloadReconstruction(_block_hash, boxed_error)
   813→                        if matches!(**boxed_error, execution_layer::Error::EngineError(_))
   814→                    ) {
   815→                        warn!(
   816→                            info = "this may occur occasionally when the EE is busy",
   817→                            block_root = ?root,
   818→                            error = ?e,
   819→                            "Error rebuilding payload for peer"
   820→                        );
   821→                    } else {
   822→                        error!(
   823→                            block_root = ?root,
   824→                            error = ?e,
   825→                            "Error fetching block for peer"
   826→                        );
   827→                    }
   828→                    log_results(peer_id, blocks_sent);
   829→                    // send the stream terminator
   830→                    return Err((RpcErrorResponse::ServerError, "Failed fetching blocks"));
   831→                }
   832→            }
   833→        }
   834→
   835→        log_results(peer_id, blocks_sent);
   836→        Ok(())
   837→    }
   838→
   839→    fn get_block_roots_for_slot_range(
   840→        &self,
   841→        req_start_slot: u64,
   842→        req_count: u64,
   843→        req_type: &str,
   844→    ) -> Result<Vec<Hash256>, (RpcErrorResponse, &'static str)> {
   845→        let start_time = std::time::Instant::now();
   846→        let finalized_slot = self
   847→            .chain
   848→            .canonical_head
   849→            .cached_head()
   850→            .finalized_checkpoint()
   851→            .epoch
   852→            .start_slot(T::EthSpec::slots_per_epoch());
   853→
   854→        let (block_roots, source) = if req_start_slot >= finalized_slot.as_u64() {
   855→            // If the entire requested range is after finalization, use fork_choice
   856→            (
   857→                self.chain
   858→                    .block_roots_from_fork_choice(req_start_slot, req_count),
   859→                "fork_choice",
   860→            )
   861→        } else if req_start_slot + req_count <= finalized_slot.as_u64() {
   862→            // If the entire requested range is before finalization, use store
   863→            (
   864→                self.get_block_roots_from_store(req_start_slot, req_count)?,
   865→                "store",
   866→            )
   867→        } else {
   868→            // Split the request at the finalization boundary
   869→            let count_from_store = finalized_slot.as_u64() - req_start_slot;
   870→            let count_from_fork_choice = req_count - count_from_store;
   871→            let start_slot_fork_choice = finalized_slot.as_u64();
   872→
   873→            // Get roots from store (up to and including finalized slot)
   874→            let mut roots_from_store =
   875→                self.get_block_roots_from_store(req_start_slot, count_from_store)?;
   876→
   877→            // Get roots from fork choice (after finalized slot)
   878→            let roots_from_fork_choice = self
   879→                .chain
   880→                .block_roots_from_fork_choice(start_slot_fork_choice, count_from_fork_choice);
   881→
   882→            roots_from_store.extend(roots_from_fork_choice);
   883→
   884→            (roots_from_store, "mixed")
   885→        };
   886→
   887→        let elapsed = start_time.elapsed();
   888→        metrics::observe_timer_vec(
   889→            &metrics::BEACON_PROCESSOR_GET_BLOCK_ROOTS_TIME,
   890→            &[source],
   891→            elapsed,
   892→        );
   893→
   894→        debug!(
   895→            req_type,
   896→            start_slot = %req_start_slot,
   897→            req_count,
   898→            roots_count = block_roots.len(),
   899→            source,
   900→            elapsed = ?elapsed,
   901→            %finalized_slot,
   902→            "Range request block roots retrieved"
   903→        );
   904→
   905→        Ok(block_roots)
   906→    }
   907→
   908→    /// Get block roots for a `BlocksByRangeRequest` from the store using roots iterator.
   909→    fn get_block_roots_from_store(
   910→        &self,
   911→        start_slot: u64,
   912→        count: u64,
   913→    ) -> Result<Vec<Hash256>, (RpcErrorResponse, &'static str)> {
   914→        let forwards_block_root_iter =
   915→            match self.chain.forwards_iter_block_roots(Slot::from(start_slot)) {
   916→                Ok(iter) => iter,
   917→                Err(BeaconChainError::HistoricalBlockOutOfRange {
   918→                    slot,
   919→                    oldest_block_slot,
   920→                }) => {
   921→                    debug!(
   922→                        requested_slot = %slot,
   923→                        oldest_known_slot = %oldest_block_slot,
   924→                        "Range request failed during backfill"
   925→                    );
   926→                    return Err((RpcErrorResponse::ResourceUnavailable, "Backfilling"));
   927→                }
   928→                Err(e) => {
   929→                    error!(
   930→                        %start_slot,
   931→                        count,
   932→                        error = ?e,
   933→                        "Unable to obtain root iter for range request"
   934→                    );
   935→                    return Err((RpcErrorResponse::ServerError, "Database error"));
   936→                }
   937→            };
   938→
   939→        // Pick out the required blocks, ignoring skip-slots.
   940→        let maybe_block_roots = process_results(forwards_block_root_iter, |iter| {
   941→            iter.take_while(|(_, slot)| slot.as_u64() < start_slot.saturating_add(count))
   942→                .collect::<Vec<_>>()
   943→        });
   944→
   945→        let block_roots = match maybe_block_roots {
   946→            Ok(block_roots) => block_roots,
   947→            Err(e) => {
   948→                error!(
   949→                    %start_slot,
   950→                    count,
   951→                    error = ?e,
   952→                    "Error during iteration over blocks for range request"
   953→                );
   954→                return Err((RpcErrorResponse::ServerError, "Iteration error"));
   955→            }
   956→        };
   957→
   958→        // remove all skip slots i.e. duplicated roots
   959→        Ok(block_roots
   960→            .into_iter()
   961→            .map(|(root, _)| root)
   962→            .unique()
   963→            .collect::<Vec<_>>())
   964→    }
